-- 服务端物品中文名补齐：item_template_locale 里 9,270 件物品要么没有 zhCN 行、要么 Name 是空的/照抄英文，
-- 导致背包悬浮提示、聊天物品链接、拍卖行搜索结果这三处显示英文名（这三处读服务端下发，不读客户端 DBC）。
-- 中文名一律取自已装机客户端的 ItemAddon.dbc zhCN 名称列（按物品 ID 配对，不是行序），
-- 保证幻化窗口（读 DBC）与服务端下发（读本表）两处叫法完全一致。
-- 生成脚本：Tempfiles/gen_item_zhcn_sql.py；核对脚本：Tempfiles/check_item_zhcn_sql.py。
-- By leewheel 2026年11月2日
